<?php

declare(strict_types=1);namespace ProjectPress\Tests\Unit;use PHPUnit\Framework\TestCase;use ProjectPress\API\DeliveryRoutes;use ProjectPress\Includes\Core\Schema;use ProjectPress\Includes\Core\WP\Database;use ProjectPress\Includes\Project\Delivery\Deployment;use ProjectPress\Includes\Project\Delivery\Environment;use ProjectPress\Includes\Project\Delivery\Release;use ProjectPress\Includes\Project\Delivery\Sprint;final class PhaseNineDeliveryTest extends TestCase{public function testDeliveryTablesAreRegistered():void{Schema::register_tables();$tables=Database::get_core_tables();foreach(array('sprints','releases','deployments','environments')as$table)$this->assertArrayHasKey($table,$tables);}public function testDeliveryModelsRemainProjectScoped():void{foreach(array(new Sprint(array('project_id'=>18)),new Release(array('project_id'=>18)),new Deployment(array('project_id'=>18)),new Environment(array('project_id'=>18)))as$model)$this->assertSame(18,$model->get_project_id());}public function testDeliveryRestHandlersExist():void{foreach(array('index','create','update','delete','can_read','can_edit')as$method)$this->assertTrue(method_exists(DeliveryRoutes::class,$method));}public function testDeletionOwnsDeliveryTables():void{$source=file_get_contents(dirname(__DIR__,2).'/src/Includes/Project/Core/ProjectRepository.php');foreach(array("'sprints'","'releases'","'deployments'","'environments'")as$table)$this->assertStringContainsString($table,$source);}}
